#include <bits/stdc++.h>
using namespace std;
#define int long long
const int mod1=998244353;
const int mod2=1e9+7;
int answer;
int total;
int count1;
vector<int> values[7];
int totalSum[7];
void generateValues(int level,int prefix){
	if(level==7) return;
	values[level].push_back((count1 - prefix + mod1) % mod1);
	totalSum[level] += (count1 - prefix + mod1) % mod1;
	count1++;
	for(int digit=0; digit<=9; ++digit){
		generateValues(level+1, prefix*10 + digit);
	}
}
bool isInRange(int x){
	const int half=1000000;
	return x*half+999999 <= total && x*half*10 > total;
}
int count2;
int powerOfTen[7]={1,10,100,1000,10000,100000,1000000};
void explore(int level,int number){
	if(number > total) return;
	if(isInRange(number)){
		for(int i=0; i<=6; ++i){
			int offset = ((count2+1 - (number*powerOfTen[i])) % mod1 + mod1) % mod1;
			int pos = lower_bound(values[i].begin(), values[i].end(), mod1 - offset) - values[i].begin();
			answer += (totalSum[i] + offset * (int)values[i].size() - mod1 * ((int)values[i].size() - pos)) % mod2;
			answer %= mod2;
		}
		count2 += count1;
	}
	else{
		count2++;
		answer += ((count2 - number) % mod1 + mod1) % mod1;
		answer %= mod2;
		for(int digit=0; digit<=9; ++digit){
			if(level==0 && digit==0) continue; // optional: skip leading zeros if needed
			explore(level+1, number*10 + digit);
		}
	}
}
int main(){
	cin >> total;
	generateValues(0,0);
	for(int i=0; i<=6; ++i) sort(values[i].begin(), values[i].end());
	count2 = -1;
	explore(0,0);
	cout << answer << "\n";
}
